dule -->\n\nPageNotFoundViewRoutingModule->PageNotFoundViewModule\n\n\n\n\n\nSharedModule\n\nSharedModule\n\nPageNotFoundViewModule -->\n\nSharedModule->PageNotFoundViewModule\n\n\n\n\n\n\n    \n    \n    \n        Zoom in\n        Reset\n        Zoom out\n    \n\n\n\n\n\n    \n        Info\n    \n    \n        Source\n    \n\n\n\n    \n\n        \n            File\n        \n        \n            src/app/views/page-not-found-view/page-not-found-view.module.ts\n        \n\n\n\n        \n            Description\n        \n        \n            The pageNotFoundView module.\nIt embeds the PageNotFoundViewComponent and its\nrouting definition\nas well as the SharedModule.\n\n        \n\n\n        \n            \n                \n                    Declarations\n                    \n                        \n                            PageNotFoundViewComponent\n                        \n                    \n                \n                \n                    Imports\n                    \n                        \n                            PageNotFoundViewRoutingModule\n                        \n                        \n                            SharedModule\n                        \n                    \n                \n            \n        \n\n\n    \n\n\n    \n        import { NgModule } from '@angular/core';\nimport { SharedModule } from '@awg-shared/shared.module';\n\n/* Routing Module */\nimport { PageNotFoundViewRoutingModule, routedPageNotFoundViewComponents } from './page-not-found-view-routing.module';\n\n/**\n * The pageNotFoundView module.\n *\n * It embeds the {@link PageNotFoundViewComponent} and its\n * [routing definition]{@link PageNotFoundViewRoutingModule}\n * as well as the {@link SharedModule}.\n */\n@NgModule({\n    imports: [SharedModule, PageNotFoundViewRoutingModule],\n    declarations: [routedPageNotFoundViewComponents],\n})\nexport class PageNotFoundViewModule {}\n\n    \n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n\n                   